code:
# 构造特征列：按大白话公式逐行生成一个新列（列编号按勾选顺序 = a、b、c…）
# 示例：a[i]/b[i]（a 列 ÷ b 列）、a[i]-b[i]、ln(a[i])、a[i]**2、(a[i]-b[i])/b[i]
# 统计：sum(a[i])（满足筛选行的 a 合计，等价 sum(a)）、mean(a[i])、a[i]/sum(a[i])（占比）、
#       (a[i]-mean(a[i]))/std(a[i])（标准化）、cumsum(a)[i]（从第 1 行累计到当前行）
# 筛选：「筛选行」参数只让满足条件的行参与计算与填值，例如 b[i] == '蔬菜'、b[i] > 5
import io
import ast
import re as _re
import math
import numpy as np
import pandas as pd


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


_df = _to_frame(data).reset_index(drop=True)
if _df.empty:
    raise RuntimeError('原始表是空的，没有行可构造新列')

_cols = {{source_cols}}
if not isinstance(_cols, list) or not _cols:
    raise RuntimeError('请先在参数区选择至少一个构造列（第一个 = a，第二个 = b…）')
if len(_cols) > 26:
    raise RuntimeError('最多选择 26 个构造列（a~z）')
_available_cols = [str(c) for c in _df.columns]
for _c in _cols:
    if _c not in _available_cols:
        raise RuntimeError('构造列「' + str(_c) + '」不在原始表中')

_aliases = 'abcdefghijklmnopqrstuvwxyz'
_col_letters = {_aliases[_idx]: str(_cols[_idx]) for _idx in range(len(_cols))}


def _num_value(_v):
    # 空值 → NaN；数字 → float；长得像数字的文本（如 '3.5'）→ float；纯文本原样保留（运算时按类型错置空）
    if _v is None:
        return np.nan
    if isinstance(_v, str):
        _s = _v.strip()
        if _s == '':
            return np.nan
        try:
            return float(_s)
        except ValueError:
            return _v
    try:
        _f = float(_v)
    except Exception:
        return _v
    if np.isnan(_f) or np.isinf(_f):
        return np.nan
    return _f


_col_values = {}
for _letter, _colname in _col_letters.items():
    _col_values[_letter] = [_num_value(_x) for _x in _df[_colname].tolist()]


def _is_empty(_v):
    if _v is None:
        return True
    if isinstance(_v, float) and pd.isna(_v):
        return True
    if isinstance(_v, str):
        return _v.strip() == ''
    return False


class _Empty:
    def __eq__(self, other):
        return _is_empty(other)

    def __ne__(self, other):
        return not _is_empty(other)

    def __repr__(self):
        return '空'


_EMPTY_ = _Empty()


def _mod_contains_(value, sub):
    if _is_empty(value):
        return False
    return str(sub) in str(value)


# ---------- 筛选行（可选） ----------
_raw_cond_text = {{row_cond}}
_has_cond = isinstance(_raw_cond_text, str) and bool(_raw_cond_text.strip())
if _has_cond:
    _cond = _raw_cond_text.strip()
    _cond = _cond.replace('== 空', '== _EMPTY_').replace('!= 空', '!= _EMPTY_')
    _cond = _cond.replace('==空', '== _EMPTY_').replace('!=空', '!= _EMPTY_')

    def _contains_repl(_m):
        return '_mod_contains_(' + _m.group(1) + '[' + _m.group(2) + '], ' + _m.group(3) + ')'
    _cond = _re.sub(r"([a-z])\s*\[\s*([^\]]+?)\s*\]\s*包含\s*('[^']*'|\"[^\"]*\")", _contains_repl, _cond)
    if '包含' in _cond:
        raise RuntimeError('「包含」用法示例：b[i] 包含 \'临时\'（筛选 b 列文本含“临时”的行）')
    try:
        _cond_ast = ast.parse(_cond, mode='eval')
    except SyntaxError as _err:
        raise RuntimeError('筛选条件语法有误：' + str(_err) + '（示例：b[i] == \'蔬菜\'、b[i] > 5、a[i] != 空）')
    _cond_mask = []
    for _i in range(len(_df)):
        _ns_c = {'i': _i, '_EMPTY_': _EMPTY_, '_mod_contains_': _mod_contains_}
        _ns_c.update(_col_values)
        try:
            _cond_mask.append(bool(eval(_cond, {'__builtins__': {}}, _ns_c)))
        except Exception as _err:
            raise RuntimeError('筛选条件在第 ' + str(_i + 1) + ' 行执行失败：' + str(_err) + '（数值列才能比大小；文本列用 == \'xx\' 或 包含）')
else:
    _cond = ''
    _cond_mask = [True] * len(_df)

_sel_rows = [_i for _i, _m in enumerate(_cond_mask) if _m]
if not _sel_rows:
    raise RuntimeError('没有行满足筛选条件「' + _cond + '」。请放宽筛选，或先检查条件里的列名/写法（示例：b[i] == \'蔬菜\'）')

# 累计缓存（cumsum(a)[i]：只对满足筛选条件的行做累计，其他行留空）
_cum_cache = {}
for _letter in _col_letters:
    _sub_vals = [_col_values[_letter][_ri] for _ri in _sel_rows]
    _sub_nums = []
    for _v in _sub_vals:
        if isinstance(_v, (int, float)) and not (isinstance(_v, float) and pd.isna(_v)):
            _sub_nums.append(float(_v))
        else:
            _sub_nums.append(0.0)  # 空值/文本不参与累计（跳过继续）
    _cum_sub = list(np.cumsum(np.asarray(_sub_nums, dtype=float)))
    _cum_full = [np.nan] * len(_df)
    for _pos, _ri in enumerate(_sel_rows):
        _cum_full[_ri] = _cum_sub[_pos]
    _cum_cache[_letter] = _cum_full

# ---------- 公式 ----------
_raw_formula = {{formula}}
if not isinstance(_raw_formula, str) or not _raw_formula.strip():
    raise RuntimeError('请填写构造公式。示例：a[i]/b[i]（a 列 ÷ b 列）、a[i]-b[i]、ln(a[i])、a[i]**2、sum(a[i])（合计）')
_formula = _raw_formula.strip()

try:
    _formula_ast = ast.parse(_formula, mode='eval')
except SyntaxError as _err:
    raise RuntimeError('构造公式语法有误：' + str(_err) + '（示例：a[i]/b[i]、a[i]-b[i]、sum(a[i])）')

# 小白可用的行内函数（多字母）；单字母 a~z 代表勾选的构造列；i 代表行号
_FUNC = {
    'abs': abs, 'round': round, 'sqrt': math.sqrt, 'ln': math.log,
    'log10': math.log10, 'exp': math.exp,
}
_AGG_FUNCS = ('sum', 'mean', 'median', 'count', 'size', 'std', 'var')


def _numeric_list(_vals):
    _out = []
    for _v in _vals:
        if isinstance(_v, (int, float)) and not (isinstance(_v, float) and pd.isna(_v)):
            _out.append(float(_v))
    return _out


def _agg_of(_name, _vals):
    _nums = _numeric_list(_vals)
    if _name == 'sum':
        return float(np.sum(_nums)) if _nums else np.nan
    if _name == 'mean':
        return float(np.mean(_nums)) if _nums else np.nan
    if _name == 'median':
        return float(np.median(_nums)) if _nums else np.nan
    if _name == 'std':
        return float(np.std(_nums, ddof=1)) if len(_nums) > 1 else np.nan
    if _name == 'var':
        return float(np.var(_nums, ddof=1)) if len(_nums) > 1 else np.nan
    if _name == 'count':
        return float(sum(0 if _is_empty(_v) else 1 for _v in _vals))
    if _name == 'size':
        return float(len(_vals))
    if _name == 'max':
        return float(max(_nums)) if _nums else np.nan
    if _name == 'min':
        return float(min(_nums)) if _nums else np.nan
    return np.nan


# 预检：收集需要预计算的聚合调用（sum/mean/…/size，以及单参的 max/min），拒绝嵌套
_agg_calls = []  # (start, end, funcname, param_text)
for _node in ast.walk(_formula_ast):
    if isinstance(_node, ast.Call) and isinstance(_node.func, ast.Name):
        _fn = _node.func.id
        _is_agg = _fn in _AGG_FUNCS or (_fn in ('min', 'max') and len(_node.args) == 1)
        if _is_agg:
            if len(_node.args) != 1:
                raise RuntimeError(_fn + '() 一次只统计一个东西。示例：' + _fn + '(a[i])；两列相加请写 a[i] + b[i]')
            for _inner in ast.walk(_node):
                if _inner is not _node and isinstance(_inner, ast.Call) and isinstance(_inner.func, ast.Name) and _inner.func.id in _AGG_FUNCS:
                    raise RuntimeError('暂不支持在 ' + _fn + '() 里再套统计函数')
            _seg = ast.get_source_segment(_formula, _node)
            _lp = _formula.find('(', _node.col_offset, _node.end_col_offset)
            _param = _formula[_lp + 1:_node.end_col_offset - 1].strip()
            _agg_calls.append((_node.col_offset, _node.end_col_offset, _fn, _param, _seg))
        elif len(_fn) == 1 and 'a' <= _fn <= 'z' and _fn != 'i':
            if _fn not in _col_letters:
                raise RuntimeError(
                    '公式用到了「' + _fn + '」列，但「构造列」只勾选了 ' + str(len(_cols)) + ' 个'
                    '（' + '、'.join(_col_letters.keys()) + '）。要么补勾这一列，要么改公式'
                )
        elif _fn not in _FUNC and _fn != 'i' and _fn not in _AGG_FUNCS and _fn not in ('min', 'max', 'cumsum'):
            raise RuntimeError(
                '公式里不能直接用「' + _fn + '」。支持的函数：sum 合计 / mean 平均 / median 中位数 / max、min /'
                ' count 非空数 / size 总行数 / std 标准差 / var 方差 / cumsum 累计 / abs / round / sqrt / ln / log10 / exp'
            )

# 收集 cumsum(字母)[i] 形式（Subscript 模式：Call(cumsum, a) 再取 [i]）
for _node in ast.walk(_formula_ast):
    if (isinstance(_node, ast.Subscript)
            and isinstance(_node.slice, ast.Name) and _node.slice.id == 'i'
            and isinstance(_node.value, ast.Call)
            and isinstance(_node.value.func, ast.Name) and _node.value.func.id == 'cumsum'
            and len(_node.value.args) == 1
            and isinstance(_node.value.args[0], ast.Name)
            and _node.value.args[0].id in _col_values):
        # 只替换 cumsum(a) 部分，保留 [i]：公式变成 _agg_0[i]
        _agg_calls.append((_node.value.col_offset, _node.value.end_col_offset, '__cum__', _node.value.args[0].id, None))
# 注意：上面的循环同时承担了“未知名称”校验，但 max/min 作为行内函数时其参数里的列/函数名不会被
# 检查——补一轮常规名称校验（跳过聚合调用自身，避免把参数里的 a[i] 当未知名）
for _node in ast.walk(_formula_ast):
    if isinstance(_node, ast.Name):
        _nm = _node.id
        if _nm == 'i' or _nm in _col_letters:
            continue
        if len(_nm) == 1 and 'a' <= _nm <= 'z':
            raise RuntimeError(
                '公式用到了「' + _nm + '」列，但「构造列」只勾选了 ' + str(len(_cols)) + ' 个'
                '（' + '、'.join(_col_letters.keys()) + '）。要么补勾这一列，要么改公式'
            )
        if _nm not in _FUNC and _nm not in _AGG_FUNCS and _nm not in ('min', 'max', 'cumsum'):
            raise RuntimeError(
                '公式里不能直接用「' + _nm + '」。支持的函数：sum 合计 / mean 平均 / median 中位数 / max、min /'
                ' count 非空数 / size 总行数 / std 标准差 / var 方差 / cumsum 累计 / abs / round / sqrt / ln / log10 / exp'
            )

# 逐段预计算聚合值（按位置从后往前替换最稳）；_orig_formula_disp 保留用户原文用于展示/报错
_orig_formula_disp = _formula
if _agg_calls:
    _agg_names = {}
    _agg_idx = 0
    for _call in sorted(_agg_calls, key=lambda c: c[0], reverse=True):
        _start, _end, _fnname, _param, _seg = _call
        if _fnname == '__cum__':
            _agg_val = _cum_cache[_param]  # 预计算的整列累计数组（含 [i] 下标取当前行）
        elif _re.search(r'\[[^\]]*\]', _param):
            # 按行收集：sum(a[i]) = 对所有满足筛选条件的 i 累加 a[i]；也支持 sum(a[i]*b[i]) 等
            _vals = []
            for _ri in _sel_rows:
                _ns_p = {'i': _ri}
                _ns_p.update(_FUNC)
                _ns_p.update(_col_values)
                try:
                    _vals.append(eval(_param, {'__builtins__': {}}, _ns_p))
                except Exception as _err:
                    raise RuntimeError(_fnname + '() 里的表达式在第 ' + str(_ri + 1) + ' 行求值失败：' + str(_err))
            _agg_val = _agg_of(_fnname, _vals)
        elif _re.fullmatch(r'[a-z]', _param) and _param in _col_values:
            # 整列模式：sum(a) 与 sum(a[i]) 等价，只统计满足筛选条件的行
            _sub = [_col_values[_param][_ri] for _ri in _sel_rows]
            _agg_val = _agg_of(_fnname, _sub)
        else:
            raise RuntimeError(_fnname + '() 参数没看懂。两种写法都行：' + _fnname + '(a[i]) 或 ' + _fnname + '(a)（a 换成你的列字母）')
        _agg_name = '_agg_' + str(_agg_idx)
        _agg_idx += 1
        _agg_names[_agg_name] = _agg_val
        _formula = _formula[:_start] + _agg_name + _formula[_end:]
    # 替换后重新解析，语法必须仍合法（聚合已变成常量名）
    try:
        _formula_ast = ast.parse(_formula, mode='eval')
    except SyntaxError as _err:
        raise RuntimeError('公式处理后有误：' + str(_err))
else:
    _agg_names = {}


def _mod_minmax(_fnname, *_args):
    if len(_args) == 1:
        _v = _args[0]
        if isinstance(_v, (list, tuple, np.ndarray)):
            _nums = _numeric_list(_v)
            if _fnname == 'max':
                return max(_nums) if _nums else np.nan
            return min(_nums) if _nums else np.nan
        return _v
    if _fnname == 'max':
        return max(_args)
    return min(_args)


# 命名空间：列 = 整列（供 cumsum 与 [i] 下标使用）
_ns_base = {'i': 0}
_ns_base.update(_FUNC)
_ns_base.update(_col_values)
_ns_base['max'] = lambda *x: _mod_minmax('max', *x)
_ns_base['min'] = lambda *x: _mod_minmax('min', *x)
_ns_base.update(_agg_names)

# ---------- 新列名：留空自动取名 ----------
_raw_name = {{new_col}}
_new_name = str(_raw_name).strip() if _raw_name else ''
if not _new_name:
    _new_name = '特征'
_name_base = _new_name
_name_seq = 2
while _new_name in _available_cols:
    _new_name = _name_base + '_' + str(_name_seq)
    _name_seq += 1


def _to_result(_v):
    if _v is None:
        raise ValueError('_EMPTY_')
    if isinstance(_v, bool):
        return 1.0 if _v else 0.0
    if isinstance(_v, str):
        _s = _v.strip()
        if _s == '':
            raise ValueError('_EMPTY_')
        try:
            return float(_s)
        except ValueError:
            raise ValueError('_TEXT_')
    try:
        _f = float(_v)
    except Exception:
        raise ValueError('_TEXT_')
    if np.isnan(_f):
        raise ValueError('_EMPTY_')
    return _f


_ok_rows = 0
_zero_rows = 0
_type_rows = 0
_empty_rows = 0
_skipped_rows = 0
_result_col = [np.nan] * len(_df)
_first_samples = []
for _i in range(len(_df)):
    if not _cond_mask[_i]:
        _skipped_rows += 1
        continue
    _ns = dict(_ns_base)
    _ns['i'] = _i
    try:
        _row_num = _to_result(eval(_formula, {'__builtins__': {}}, _ns))
    except ZeroDivisionError:
        _zero_rows += 1
        continue
    except ValueError as _err:
        if str(_err) == '_EMPTY_':
            _empty_rows += 1
        else:
            _type_rows += 1
        continue
    except (TypeError, OverflowError):
        _type_rows += 1
        continue
    except NameError:
        raise RuntimeError(
            '公式在第 ' + str(_i + 1) + ' 行用到了不认识的名称。可用的列：'
            + '、'.join(_col_letters.keys()) + '；可用的函数：sum/mean/median/max/min/count/size/std/var/cumsum/abs/round/sqrt/ln/log10/exp'
        )
    except Exception as _err:
        raise RuntimeError(
            '公式在第 ' + str(_i + 1) + ' 行执行失败：' + str(_err)
            + '（示例：a[i]/b[i]、a[i]-b[i]、ln(a[i])、sum(a[i])）'
        )
    _result_col[_i] = _row_num
    _ok_rows += 1
    if len(_first_samples) < 3:
        _first_samples.append({'行': _i + 1, '结果': _row_num})

if _ok_rows == 0:
    if _has_cond:
        raise RuntimeError(
            '每一行都没能算出结果：筛选条件可能太严或公式与列不匹配（公式 ' + _orig_formula_disp + '）。'
            '可先去掉筛选条件试试'
        )
    raise RuntimeError(
        '每一行都没能算出结果。请检查公式和构造列是否搭配（公式 ' + _orig_formula_disp
        + ' 需要参与的列都是数字；文本/空值行会被置空）。'
    )

_df_out = _df.copy()
_df_out[_new_name] = _result_col

_report = {
    '公式': _orig_formula_disp,
    '构造列编号': {_l: _col_letters[_l] for _l in _col_letters},
    '新列名': _new_name,
    '筛选条件': _cond if _has_cond else '（不过滤）',
    '原始行数': len(_df),
    '满足筛选行数': len(_sel_rows),
    '被筛选跳过行数': _skipped_rows,
    '成功行数': _ok_rows,
    '置空行数': len(_sel_rows) - _ok_rows,
    '置空原因': {
        '分母为零': _zero_rows,
        '值不是数字或公式报错': _type_rows,
        '原始值有空值': _empty_rows,
    },
    '结果预览': [{'行': _s['行'], '结果': round(_s['结果'], 4)} for _s in _first_samples],
}

return {'data': _df_out, 'report': _report}
